"""Media bundle routing and reference-image composition nodes."""

from __future__ import annotations

import math
from collections.abc import Mapping
from fractions import Fraction
from typing import Any

import torch

from ..core.video_api import make_video_components


MEDIA_BUNDLE_TYPE = "MINIMAX_H3_MEDIA_BUNDLE"
MEDIA_SPLITTER_MAX_IMAGES = 27
MEDIA_SPLITTER_MAX_VIDEOS = 9
MEDIA_SPLITTER_MAX_AUDIOS = 9
MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK = "block_missing"
MEDIA_SPLITTER_EMPTY_OUTPUT_NONE = "allow_none"
MEDIA_SPLITTER_EMPTY_OUTPUT_MODES = (
    MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK,
    MEDIA_SPLITTER_EMPTY_OUTPUT_NONE,
)


def _execution_blocker() -> Any:
    """Return ComfyUI's blocker without making tests import the full runtime."""
    try:
        from comfy_execution.graph import ExecutionBlocker
    except Exception:
        return None
    return ExecutionBlocker(None)


def _bundle_items(media_bundle: Any) -> list[Any]:
    """Read the native H3 bundle and a small mapping-based compatibility shape."""
    items = getattr(media_bundle, "items", None)
    if items is not None and not callable(items):
        return list(items)
    if isinstance(media_bundle, Mapping):
        raw_items = media_bundle.get("items")
        if isinstance(raw_items, (list, tuple)):
            return list(raw_items)
        result: list[Any] = []
        for kind in ("image", "audio", "video"):
            values = media_bundle.get(f"{kind}s", media_bundle.get(kind, []))
            if values is None:
                continue
            if not isinstance(values, (list, tuple)):
                values = [values]
            result.extend({"media_type": kind, "value": value} for value in values)
        return result
    raise ValueError("请连接 MiniMax H3 Easy 媒体加载器输出的媒体包")


def _item_parts(item: Any) -> tuple[str, Any] | None:
    if isinstance(item, Mapping):
        media_type = item.get("media_type", item.get("type", item.get("kind")))
        value = item.get("value", item.get("data", item.get("media")))
    else:
        media_type = getattr(item, "media_type", getattr(item, "type", getattr(item, "kind", None)))
        value = getattr(item, "value", getattr(item, "data", getattr(item, "media", None)))
        if media_type is None and isinstance(item, (list, tuple)) and len(item) >= 2:
            media_type = item[-2]
            value = item[-1]

    normalized = str(media_type or "").strip().lower()
    aliases = {
        "image": "image",
        "images": "image",
        "img": "image",
        "picture": "image",
        "audio": "audio",
        "audios": "audio",
        "sound": "audio",
        "video": "video",
        "videos": "video",
        "movie": "video",
    }
    kind = aliases.get(normalized)
    return (kind, value) if kind is not None else None


def _image_values(value: Any) -> list[torch.Tensor]:
    """Flatten IMAGE batches while retaining a one-image batch per output item."""
    if isinstance(value, torch.Tensor):
        if value.ndim == 4:
            return [value[index : index + 1] for index in range(int(value.shape[0]))]
        if value.ndim == 3:
            return [value.unsqueeze(0)]
        raise ValueError("媒体包中的图像必须是 HWC 或 BHWC 张量")
    if isinstance(value, (list, tuple)):
        result: list[torch.Tensor] = []
        for item in value:
            result.extend(_image_values(item))
        return result
    raise ValueError("媒体包包含无法识别的图像数据")


def _audio_values(value: Any) -> list[Any]:
    if isinstance(value, (list, tuple)):
        result: list[Any] = []
        for item in value:
            result.extend(_audio_values(item))
        return result
    if isinstance(value, Mapping) and isinstance(value.get("waveform"), torch.Tensor):
        return [value]
    raise ValueError("媒体包中的音频必须包含 waveform")


def _video_values(value: Any) -> list[Any]:
    if isinstance(value, (list, tuple)):
        result: list[Any] = []
        for item in value:
            result.extend(_video_values(item))
        return result
    return [_standard_video(value)]


def _standard_video(value: Any) -> Any:
    """Convert the H3 loader's cached mapping into ComfyUI's VIDEO value."""
    if hasattr(value, "get_components"):
        return value
    if not isinstance(value, Mapping):
        raise ValueError("媒体包中的视频格式无法识别")

    nested = value.get("video")
    if nested is not None and nested is not value:
        return _standard_video(nested)

    frames = value.get("images", value.get("frames"))
    if not isinstance(frames, torch.Tensor) or frames.ndim != 4 or frames.shape[0] < 1:
        raise ValueError("媒体包中的视频没有有效帧")
    fps = value.get("fps", value.get("frame_rate", 24.0)) or 24.0
    try:
        frame_rate = Fraction(str(float(fps)))
    except (TypeError, ValueError) as exc:
        raise ValueError("媒体包中的视频 FPS 无效") from exc

    audio = value.get("audio")
    audio_payload = None
    if isinstance(audio, Mapping) and isinstance(audio.get("waveform"), torch.Tensor):
        audio_payload = audio
    components = make_video_components(
        frames,
        audio=audio_payload,
        frame_rate=frame_rate,
        metadata=value.get("metadata"),
        alpha=value.get("alpha"),
    )
    try:
        from comfy_api.latest import InputImpl

        return InputImpl.VideoFromComponents(components)
    except TypeError as exc:
        # Older VIDEO APIs may reject metadata or alpha even after the helper's
        # component fallback. Retry with the smallest valid component payload.
        if "metadata" in str(exc) or "alpha" in str(exc):
            components = make_video_components(
                frames,
                audio=audio_payload,
                frame_rate=frame_rate,
            )
            return InputImpl.VideoFromComponents(components)
        raise


def _normalize_image(image: torch.Tensor, *, max_edge: int) -> torch.Tensor:
    image = image[:1]
    if image.ndim != 4 or image.shape[0] != 1:
        raise ValueError("图像批次形状必须是 [1,H,W,C]")
    if image.shape[-1] == 1:
        image = image.repeat(1, 1, 1, 3)
    elif image.shape[-1] >= 3:
        image = image[..., :3]
    else:
        raise ValueError("图像必须至少包含一个颜色通道")
    if not torch.is_floating_point(image):
        image = image.float()
        if float(image.max().item()) > 1.0:
            image = image / 255.0
    image = image.clamp(0.0, 1.0)

    height, width = int(image.shape[1]), int(image.shape[2])
    longest = max(height, width)
    if longest <= max_edge:
        return image
    scale = max_edge / float(longest)
    target_height = max(1, int(round(height * scale)))
    target_width = max(1, int(round(width * scale)))
    image = torch.nn.functional.interpolate(
        image.permute(0, 3, 1, 2),
        size=(target_height, target_width),
        mode="bilinear",
        align_corners=False,
    )
    return image.permute(0, 2, 3, 1).contiguous()


def _compose_images(images: list[torch.Tensor], max_edge: int = 1024) -> torch.Tensor | None:
    if not images:
        return None
    max_edge = max(64, min(int(max_edge), 4096))
    normalized = [_normalize_image(image, max_edge=max_edge) for image in images]
    cell_height = max(int(image.shape[1]) for image in normalized)
    cell_width = max(int(image.shape[2]) for image in normalized)
    columns = max(1, int(math.ceil(math.sqrt(len(normalized)))))
    rows = int(math.ceil(len(normalized) / columns))
    first = normalized[0]
    canvas = torch.zeros(
        (1, rows * cell_height, columns * cell_width, 3),
        dtype=first.dtype,
        device=first.device,
    )
    for index, image in enumerate(normalized):
        row, column = divmod(index, columns)
        height, width = int(image.shape[1]), int(image.shape[2])
        top = row * cell_height + (cell_height - height) // 2
        left = column * cell_width + (cell_width - width) // 2
        canvas[:, top : top + height, left : left + width, :] = image.to(
            device=canvas.device,
            dtype=canvas.dtype,
        )
    return canvas


class WyslMediaAutoSplitter:
    """Split a mixed H3 media bundle and optionally compose its images."""

    CATEGORY = "Wysl/工具"
    FUNCTION = "split"
    RETURN_TYPES = ("IMAGE", "AUDIO", "VIDEO", "IMAGE")
    RETURN_NAMES = ("图像", "音频", "视频", "图片组合")
    OUTPUT_IS_LIST = (True, True, True, False)
    DESCRIPTION = (
        "自动识别媒体包中的图像、音频和视频；前三个输出保留输入顺序，"
        "图片组合输出会把所有图像按自动网格拼接为一张图。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "media_bundle": (MEDIA_BUNDLE_TYPE,),
                "组合图片长边": (
                    "INT",
                    {
                        "default": 1024,
                        "min": 64,
                        "max": 4096,
                        "step": 64,
                        "tooltip": "仅影响图片组合输出；图像列表输出保持原始分辨率。",
                    },
                ),
            }
        }

    @staticmethod
    def split(media_bundle, 组合图片长边=1024):
        images: list[torch.Tensor] = []
        audios: list[Any] = []
        videos: list[Any] = []
        for item in _bundle_items(media_bundle):
            parts = _item_parts(item)
            if parts is None:
                continue
            kind, value = parts
            if kind == "image":
                images.extend(_image_values(value))
            elif kind == "audio":
                audios.extend(_audio_values(value))
            elif kind == "video":
                videos.extend(_video_values(value))

        image_output = images if images else _execution_blocker()
        audio_output = audios if audios else _execution_blocker()
        video_output = videos if videos else _execution_blocker()
        combined = _compose_images(images, int(组合图片长边))
        combined_output = combined if combined is not None else _execution_blocker()
        return image_output, audio_output, video_output, combined_output


def _flatten_input_values(value: Any) -> list[Any]:
    """Flatten ComfyUI list inputs without splitting tensor batches here."""
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        result: list[Any] = []
        for item in value:
            result.extend(_flatten_input_values(item))
        return result
    return [value]


def _single_input_value(value: Any, default: Any = None) -> Any:
    """Unwrap a scalar passed through ComfyUI's ``INPUT_IS_LIST`` contract."""
    if value is None:
        return default
    if isinstance(value, (list, tuple)):
        return value[0] if value else default
    return value


def _bundle_items_from_input(value: Any) -> list[Any]:
    """Accept one bundle or a list-wrapped bundle from INPUT_IS_LIST."""
    result: list[Any] = []
    for item in _flatten_input_values(value):
        if item is None:
            continue
        result.extend(_bundle_items(item))
    return result


def _normalize_empty_output_mode(value: Any) -> str:
    raw = str(value or MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK).strip().casefold()
    compact = raw.replace(" ", "").replace("（", "(").replace("）", ")")
    if compact in {
        MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK,
        "original",
        "original mode",
        "默认(跳过缺失输出)",
        "跳过缺失输出",
        "原有模式(空端口不报错)",
        "原有模式(空端口阻断)",
        "媒体数量校验",
        "mediacountcheck",
        "严格模式",
        "strict",
        "error",
    }:
        return MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK
    if compact in {
        MEDIA_SPLITTER_EMPTY_OUTPUT_NONE,
        "none",
        "允许空输出",
        "允许空输出(None)",
        "allow empty outputs",
    }:
        return MEDIA_SPLITTER_EMPTY_OUTPUT_NONE
    raise ValueError(
        "Wysl Media Splitter empty_output_mode must be 'block_missing' or 'allow_none'"
    )


class WyslMediaSplitter:
    """Expose individual media values from a bundle or the legacy media lists."""

    CATEGORY = "Wysl/工具"
    FUNCTION = "split"
    INPUT_IS_LIST = True
    RETURN_TYPES = ("*",) * (
        MEDIA_SPLITTER_MAX_IMAGES
        + MEDIA_SPLITTER_MAX_VIDEOS
        + MEDIA_SPLITTER_MAX_AUDIOS
    )
    RETURN_NAMES = (
        *(f"image_{index}" for index in range(1, MEDIA_SPLITTER_MAX_IMAGES + 1)),
        *(f"video_{index}" for index in range(1, MEDIA_SPLITTER_MAX_VIDEOS + 1)),
        *(f"audio_{index}" for index in range(1, MEDIA_SPLITTER_MAX_AUDIOS + 1)),
    )
    DESCRIPTION = (
        "将媒体包或多媒体加载器的图像、视频、音频列表拆成独立接口；"
        "媒体类型互不混合，输出数量由三个数量控件决定。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "image_count": (
                    "INT",
                    {"default": 1, "min": 0, "max": MEDIA_SPLITTER_MAX_IMAGES, "step": 1},
                ),
                "video_count": (
                    "INT",
                    {"default": 0, "min": 0, "max": MEDIA_SPLITTER_MAX_VIDEOS, "step": 1},
                ),
                "audio_count": (
                    "INT",
                    {"default": 0, "min": 0, "max": MEDIA_SPLITTER_MAX_AUDIOS, "step": 1},
                ),
                "empty_output_mode": (
                    [
                        MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK,
                        MEDIA_SPLITTER_EMPTY_OUTPUT_NONE,
                    ],
                    {"default": MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK},
                ),
            },
            "optional": {
                "media_bundle": (MEDIA_BUNDLE_TYPE, {"lazy": True}),
                "images": ("IMAGE", {"lazy": True}),
                "videos": ("VIDEO", {"lazy": True}),
                "audios": ("AUDIO", {"lazy": True}),
            },
        }

    @staticmethod
    def _append_bundle_media(media_bundle: Any, images: list[Any], videos: list[Any], audios: list[Any]) -> None:
        for item in _bundle_items_from_input(media_bundle):
            parts = _item_parts(item)
            if parts is None:
                continue
            kind, value = parts
            if kind == "image":
                images.extend(_image_values(value))
            elif kind == "video":
                videos.extend(_video_values(value))
            elif kind == "audio":
                audios.extend(_audio_values(value))

    @staticmethod
    def _empty_output(mode: str) -> Any:
        return (
            _execution_blocker()
            if mode == MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK
            else None
        )

    def split(
        self,
        image_count=1,
        video_count=0,
        audio_count=0,
        empty_output_mode=MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK,
        media_bundle=None,
        images=None,
        videos=None,
        audios=None,
    ):
        image_count = _single_input_value(image_count, 1)
        video_count = _single_input_value(video_count, 0)
        audio_count = _single_input_value(audio_count, 0)
        empty_output_mode = _single_input_value(
            empty_output_mode,
            MEDIA_SPLITTER_EMPTY_OUTPUT_BLOCK,
        )
        mode = _normalize_empty_output_mode(empty_output_mode)
        counts = {
            "image": max(0, min(MEDIA_SPLITTER_MAX_IMAGES, int(image_count))),
            "video": max(0, min(MEDIA_SPLITTER_MAX_VIDEOS, int(video_count))),
            "audio": max(0, min(MEDIA_SPLITTER_MAX_AUDIOS, int(audio_count))),
        }
        image_values: list[Any] = []
        video_values: list[Any] = []
        audio_values: list[Any] = []
        self._append_bundle_media(media_bundle, image_values, video_values, audio_values)
        for value in _flatten_input_values(images):
            image_values.extend(_image_values(value))
        for value in _flatten_input_values(videos):
            video_values.extend(_video_values(value))
        for value in _flatten_input_values(audios):
            audio_values.extend(_audio_values(value))

        by_type = {
            "image": image_values,
            "video": video_values,
            "audio": audio_values,
        }
        outputs: list[Any] = []
        for kind, count in (
            ("image", counts["image"]),
            ("video", counts["video"]),
            ("audio", counts["audio"]),
        ):
            values = by_type[kind]
            for index in range(count):
                if index >= len(values):
                    outputs.append(self._empty_output(mode))
                    continue
                value = values[index]
                if kind == "video":
                    value = _standard_video(value)
                elif kind == "audio":
                    value = _audio_values(value)[0]
                outputs.append(value)
        return tuple(outputs)


NODE_CLASS_MAPPINGS = {
    "WyslMediaAutoSplitter": WyslMediaAutoSplitter,
    "WyslMediaSplitter": WyslMediaSplitter,
}

NODE_DISPLAY_NAME_MAPPINGS = {
    "WyslMediaAutoSplitter": "Wysl-自动拆分媒体",
    "WyslMediaSplitter": "Wysl-媒体拆分",
}
